def apply():
    print(f"Loading {LOYTEL_FILE}...")
    wb = openpyxl.load_workbook(LOYTEL_FILE)
    ws = wb.active
    
    headers = {ws.cell(1, c).value: c for c in range(1, ws.max_column + 1)}
    col_text = headers.get('text', 12)
    
    updated = 0
    for r, it_text in LOYTEL_PART2.items():
        if r <= ws.max_row:
            ws.cell(r, col_text, it_text)
            updated += 1
            
    wb.save(LOYTEL_FILE)
    print(f"Aggiornate con successo {updated} righe in loytel.xlsx (Part 2)")

if __name__ == '__main__':
    apply()
